<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Auth,Csrf,Database,View};

final class LotesController
{
 public function index():void {Auth::requireLogin();$db=Database::connection();$q=trim($_GET['q']??'');$sql="SELECT l.*,m.codigo,m.nombre,DATEDIFF(l.fecha_vencimiento,CURDATE()) dias FROM lotes l JOIN medicamentos m ON m.id=l.medicamento_id WHERE 1";$p=[];if($q!==''){$sql.=' AND (l.numero_lote LIKE ? OR m.nombre LIKE ? OR m.codigo LIKE ?)';$x="%$q%";array_push($p,$x,$x,$x);}$sql.=' ORDER BY l.fecha_vencimiento,l.id DESC';$s=$db->prepare($sql);$s->execute($p);$lotes=$s->fetchAll();View::render('lotes/index',compact('lotes','q'));}
 public function form():void {Auth::requireAdmin();$medicamentos=Database::connection()->query('SELECT id,codigo,nombre FROM medicamentos WHERE activo=1 ORDER BY nombre')->fetchAll();View::render('lotes/form',compact('medicamentos'));}
 public function save():void {Auth::requireAdmin();Csrf::enforce();$db=Database::connection();$med=(int)($_POST['medicamento_id']??0);$numero=trim($_POST['numero_lote']??'');$ing=$_POST['fecha_ingreso']??'';$ven=$_POST['fecha_vencimiento']??'';$cant=filter_var($_POST['cantidad']??null,FILTER_VALIDATE_INT);if(!$med||$numero===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$ing)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$ven)||$cant===false||$cant<1){flash('danger','Revisa los datos del lote.');redirect('index.php?page=lote-form');}try{$db->beginTransaction();$db->prepare('INSERT INTO lotes(medicamento_id,numero_lote,fecha_ingreso,fecha_vencimiento,cantidad_inicial,cantidad_disponible,usuario_registro_id) VALUES(?,?,?,?,?,?,?)')->execute([$med,$numero,$ing,$ven,$cant,$cant,Auth::id()]);$lote=(int)$db->lastInsertId();$db->prepare("INSERT INTO movimientos_inventario(medicamento_id,lote_id,usuario_id,tipo,cantidad,stock_anterior,stock_posterior,motivo) VALUES(?,?,?,'entrada',?,0,?,'Registro de lote')")->execute([$med,$lote,Auth::id(),$cant,$cant]);$db->commit();flash('success','Lote e ingreso registrados.');}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();flash('danger','No se pudo registrar. El número de lote puede estar duplicado para este medicamento.');}redirect('index.php?page=lotes');}
 public function toggle():void {Auth::requireAdmin();Csrf::enforce();$id=(int)($_POST['id']??0);Database::connection()->prepare("UPDATE lotes SET estado=IF(estado='habilitado','bloqueado','habilitado') WHERE id=?")->execute([$id]);flash('success','Estado del lote actualizado.');redirect('index.php?page=lotes');}
 public function vencimientos():void {Auth::requireLogin();$db=Database::connection();$dias=(int)($db->query("SELECT valor FROM configuraciones WHERE clave='dias_alerta_vencimiento'")->fetchColumn()?:30);$estado=$_GET['estado']??'todos';$med=(int)($_GET['medicamento']??0);$desde=$_GET['desde']??'';$hasta=$_GET['hasta']??'';$sql="SELECT l.*,m.codigo,m.nombre,DATEDIFF(l.fecha_vencimiento,CURDATE()) dias FROM lotes l JOIN medicamentos m ON m.id=l.medicamento_id WHERE l.cantidad_disponible>0";$p=[];if($estado==='vencido')$sql.=' AND l.fecha_vencimiento<=CURDATE()';elseif($estado==='proximo'){$sql.=' AND l.fecha_vencimiento>CURDATE() AND l.fecha_vencimiento<=DATE_ADD(CURDATE(),INTERVAL ? DAY)';$p[]=$dias;}elseif($estado==='vigente'){$sql.=' AND l.fecha_vencimiento>DATE_ADD(CURDATE(),INTERVAL ? DAY)';$p[]=$dias;}if($med){$sql.=' AND l.medicamento_id=?';$p[]=$med;}if($desde){$sql.=' AND l.fecha_vencimiento>=?';$p[]=$desde;}if($hasta){$sql.=' AND l.fecha_vencimiento<=?';$p[]=$hasta;}$sql.=' ORDER BY l.fecha_vencimiento';$s=$db->prepare($sql);$s->execute($p);$lotes=$s->fetchAll();$medicamentos=$db->query('SELECT id,nombre FROM medicamentos WHERE activo=1 ORDER BY nombre')->fetchAll();View::render('lotes/vencimientos',compact('lotes','medicamentos','dias','estado','med','desde','hasta'));}
}
